begin;
create temp table checks(label text);create temp table fixture(k text primary key,v jsonb);
grant all on checks,fixture to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into checks values(label);end$$;
insert into auth.users(id,is_anonymous) values('97000000-0000-4000-8000-000000000001',false),('97000000-0000-4000-8000-000000000002',true),('97000000-0000-4000-8000-000000000003',false);
insert into pn_private.sample_accounts(owner_id,namespace) values('97000000-0000-4000-8000-000000000001','qa-video');
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) values('97000000-0000-4000-8000-000000000010','97000000-0000-4000-8000-000000000001','7B',7,3,'demo'),('97000000-0000-4000-8000-000000000011','97000000-0000-4000-8000-000000000001','real',7,3,'pilot');
insert into fixture values('state','{"schemaVersion":1,"mode":"opening","question":3,"taskEpoch":"97000000-0000-4000-8000-000000000020","groups":[]}');
set local role authenticated;set local request.jwt.claims='{"sub":"97000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select count(*)=1 from public.classes),'sample cannot read real class even under same owner');
select pg_temp.ok(public.sample_control(null,false,true)->>'error'='CONFLICT','sample missing cookie cannot control');
select pg_temp.ok(public.sample_control('97000000-0000-4000-8000-000000000030',false,true)->>'ok'='true','operator acquires sample lease');
select pg_temp.ok(public.sample_control('97000000-0000-4000-8000-000000000031',false,true)->>'error'='CONFLICT','visitor cannot silently take recording');
set local request.jwt.claims='{"sub":"97000000-0000-4000-8000-000000000002","is_anonymous":true}';
insert into fixture select 'pair',public.presentation_action('create',jsonb_build_object('codeHash',repeat('9',64),'ipHash','qa-video'));
set local request.jwt.claims='{"sub":"97000000-0000-4000-8000-000000000001","is_anonymous":false}';
insert into fixture select 'claim',jsonb_build_object('codeHash',repeat('9',64),'classId','97000000-0000-4000-8000-000000000010','sessionId','97000000-0000-4000-8000-000000000040','controllerId','97000000-0000-4000-8000-000000000050','sampleController','97000000-0000-4000-8000-000000000030','payload',(select v from fixture where k='state'));
insert into fixture select 'first',public.presentation_action('claim',(select v from fixture where k='claim'));
select pg_temp.ok((select v->'envelope'->>'revision'='1' from fixture where k='first'),'sample normal claim with lease');
set local request.jwt.claims='{"sub":"97000000-0000-4000-8000-000000000002","is_anonymous":true}';
insert into fixture select 'resume-pair',public.presentation_action('create',jsonb_build_object('codeHash',repeat('8',64),'ipHash','qa-video','presentationId',(select v->'envelope'->'presentationId' from fixture where k='first')));
set local request.jwt.claims='{"sub":"97000000-0000-4000-8000-000000000001","is_anonymous":false}';
insert into fixture select 'second',public.presentation_action('claim',(select v||jsonb_build_object('codeHash',repeat('8',64),'controllerId','97000000-0000-4000-8000-000000000051','payload',v->'payload'||'{"question":1}') from fixture where k='claim'));
select pg_temp.ok((select (v->'envelope'->>'presentationId')=(select v->'envelope'->>'presentationId' from fixture where k='first') and v->'envelope'->'payload'->>'question'='3' from fixture where k='second'),'re-scan keeps presentation and question3');
select pg_temp.ok((select v->'envelope'->>'channelEpoch'<>(select v->'envelope'->>'channelEpoch' from fixture where k='first') from fixture where k='second'),'re-scan rotates grant');
select pg_temp.ok(public.presentation_action('snapshot',jsonb_build_object('presentationId',(select v->'envelope'->'presentationId' from fixture where k='first'),'controllerId','97000000-0000-4000-8000-000000000050'))->>'error'='FORBIDDEN','displaced tab cannot recover new epoch');
select pg_temp.ok(public.presentation_logout('97000000-0000-4000-8000-000000000051','97000000-0000-4000-8000-000000000031')->>'revoked'='0','observer logout does not revoke controller');
select pg_temp.ok(public.presentation_action('snapshot',jsonb_build_object('presentationId',(select v->'envelope'->'presentationId' from fixture where k='second'),'controllerId','97000000-0000-4000-8000-000000000051'))->'envelope'->'payload'->>'question'='3','active controller survives observer logout');
select pg_temp.ok(public.presentation_logout('97000000-0000-4000-8000-000000000051','97000000-0000-4000-8000-000000000030')->>'revoked'='1','current tab logout revokes its grant');
select pg_temp.ok(public.presentation_action('resume',jsonb_build_object('sessionId','97000000-0000-4000-8000-000000000040','classId','97000000-0000-4000-8000-000000000010','controllerId','97000000-0000-4000-8000-000000000051'))->'snapshot'='null'::jsonb,'logged-out tab cannot auto-resume');
select pg_temp.ok(public.presentation_action('claim',(select v from fixture where k='claim'))->>'error' in ('NOT_FOUND','FORBIDDEN'),'old QR cannot be replayed');
select pg_temp.ok(public.sample_control('97000000-0000-4000-8000-000000000031',true,true)->>'ok'='true','authorized explicit takeover succeeds');
select pg_temp.ok(public.sample_control('97000000-0000-4000-8000-000000000030',false,false)->>'error'='CONFLICT','old sample cookie denied after takeover');
reset role;select count(*)||' video connection SQL assertions PASS' from checks;rollback;
